-- Funcionalidade 6: a goal can be paused (and come back), ended or replaced by another, never deleted. The status
-- now has four values; the old CHECKs on it are dropped (their names were generated by PostgreSQL) and named ones
-- take their place.
DO $$
DECLARE
    constraint_name text;
BEGIN
    FOR constraint_name IN
        SELECT conname FROM pg_constraint
        WHERE conrelid = 'goals.goals'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%status%'
    LOOP
        EXECUTE format('ALTER TABLE goals.goals DROP CONSTRAINT %I', constraint_name);
    END LOOP;
END $$;

ALTER TABLE goals.goals
    ADD COLUMN paused_at         timestamptz NULL,
    ADD COLUMN resume_on         date        NULL,
    ADD COLUMN resume_offered_at timestamptz NULL,
    ADD COLUMN replaced_by       uuid        NULL REFERENCES goals.goals (id),
    ADD COLUMN status_reason     text        NULL CHECK (length(status_reason) <= 500);

ALTER TABLE goals.goals
    ADD CONSTRAINT ck_goals_status CHECK (status IN ('active', 'paused', 'cancelled', 'replaced')),
    ADD CONSTRAINT ck_goals_ended CHECK ((status IN ('cancelled', 'replaced')) = (cancelled_at IS NOT NULL)),
    ADD CONSTRAINT ck_goals_paused CHECK ((status = 'paused') = (paused_at IS NOT NULL)),
    ADD CONSTRAINT ck_goals_resume CHECK (resume_on IS NULL OR status = 'paused'),
    ADD CONSTRAINT ck_goals_replaced CHECK ((status = 'replaced') = (replaced_by IS NOT NULL));

COMMENT ON COLUMN goals.goals.status IS 'active, paused (comes back), cancelled (ended by the user) or replaced (by replaced_by). Kept for the history.';
COMMENT ON COLUMN goals.goals.cancelled_at IS 'When the goal was ended: cancelled or replaced.';
COMMENT ON COLUMN goals.goals.resume_on IS 'The day a pause ends, when the user said one; Pippin then asks whether to resume.';
COMMENT ON COLUMN goals.goals.resume_offered_at IS 'Pippin already asked whether to resume (once per pause).';
COMMENT ON COLUMN goals.goals.status_reason IS 'Why the user paused, ended or replaced it, in their words.';

-- Every change of status, so the path of a goal can be told even after it is resumed, ended or replaced.
CREATE TABLE goals.goal_status_changes (
    id          uuid        PRIMARY KEY,
    goal_id     uuid        NOT NULL REFERENCES goals.goals (id) ON DELETE CASCADE,
    user_id     uuid        NOT NULL,
    from_status text        NOT NULL CHECK (from_status IN ('active', 'paused', 'cancelled', 'replaced')),
    to_status   text        NOT NULL CHECK (to_status IN ('active', 'paused', 'cancelled', 'replaced')),
    reason      text        NULL CHECK (length(reason) <= 500),
    resume_on   date        NULL,
    changed_at  timestamptz NOT NULL
);

CREATE INDEX ix_goal_status_changes_goal ON goals.goal_status_changes (goal_id, changed_at);
